// Independently authored cache regression, synthetic masks only.
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;using FakeFantasyOnline.Presentation.ReferenceAssets;using UnityEngine;
class BuildingMixedPzContract {
 class Case{public int Id,Width,Height,TextureWidth,TextureHeight;public string Path;}
 static int[] zs={0,61,-400,0,144,-148};static int checks;static void C(bool x,string m){checks++;if(!x)throw new Exception(m);}
 static int Front(int col,int h)=>col%2==0?10:((h+9)/10)*10;
 static byte[] Mask(int w,int h){using(var m=new MemoryStream())using(var b=new BinaryWriter(m)){int n=(w+9)/10;b.Write(-1);b.Write(0x10002);b.Write(new byte[50]);b.Write(n);for(int c=0;c<n;c++){b.Write(c*10+5);b.Write(Front(c,h)-5);}for(int c=0;c<n;c++)b.Write((byte)129);return m.ToArray();}}
 internal static void Run(string file){var cases=new JavaScriptSerializer().Deserialize<Case[]>(File.ReadAllText(file));foreach(var c in cases){var l=new ResLoader();ResLoader.I=l;var tex=new Texture2D(c.TextureWidth,c.TextureHeight);var im=new ResLoader.ObjSprite{path=c.Path,tex=tex,frames=1,hdScale=1};l.Images[c.Id]=im;l.Pkg.Files[c.Path.Replace(".gso",".mask")]=Mask(c.TextureWidth,c.TextureHeight);var map=new ReferenceGsmMap{Native=new GsmMap()};for(int i=0;i<zs.Length;i++)map.Native.libObjs.Add(new GsmMap.Obj{id=c.Id,sx=1000+i*1100,sy=3000+i*11,xl=c.Width,yl=c.Height,py=3000+c.Height,pz=zs[i]});var owner=new GameBootstrap();var r=new ReferenceLegacyMapObjectRenderer(map,l,new GameObject("MixedPZ").transform,objectOwner:owner);r.Build();C(ReferenceWalkableDeckProfile.TryGetMaskDeck(c.Id,c.Path,c.Width,c.Height,im,out var spans),"fixture admitted");var count=new int[zs.Length];for(int j=0;j<r.Rendered.Count;j++){var sr=r.Rendered[j];var pl=r.Placements[j];int k=pl.ObjectIndex,sy=3000+k*11;count[k]++;C(pl.ScreenY==sy-zs[k],"per-instance visual projection");var v=sr.sprite.vertices;C(v!=null,"mesh dispatch");for(int q=0;q<v.Length;q+=4){int x=(int)((v[q].x+v[q+1].x)/2);int y=tex.height-(int)Math.Ceiling((v[q].y+v[q+2].y)/2);int col=x/10,expected=Front(col,c.TextureHeight);for(int z=0;z<spans.Length;z+=4)if(x/ReferenceWalkableDeckProfile.ColumnWidth(c.Id)==spans[z]&&y>=spans[z+1]&&y<spans[z+2]){expected=Math.Min(expected,spans[z+3]-zs[k]);break;}C(sr.sortingOrder==sy+expected,"mixed-PZ source-column order mismatch "+c.Path+" index="+k+" column="+col+" actual="+sr.sortingOrder+" expected="+(sy+expected));}}C(count.All(n=>n>0),"all six instances placed");C(owner.FadeCalls==6,"one fade registration per instance");r.Dispose();}Console.WriteLine("PASS "+checks+" shared-texture mixed-PZ checks across "+cases.Length+" profiles x6 instances; synthetic masks / Unity substitutes only");}}
